\title{The Last Theorem: Countable Provability against a Finite Physical Budget}
\author{Aristotle}
\date{2026-07-12}

\begin{document}
\begin{abstract}
We formalize a simple but far-reaching tension between the structure of provable
mathematics and the physical limits of computation. Modeling a \emph{theorem} as a
finite string over a fixed finite alphabet derivable from the standard axioms of
set theory (ZFC), we prove that the collection $T$ of all theorems is countably
infinite, so every theorem occupies a finite position in a single enumeration and
is discoverable after finitely many steps. Modeling any physically realizable
discovery process as an enumerator with a finite operation budget
$N_{\max}\approx 10^{120}$ (the cosmological bound before heat death), we prove
that the discoverable fraction is zero: the natural density of any finite set
within a countably infinite enumeration vanishes. Using the Bekenstein--Hawking
relation we show a black hole of mass $M$ stores $I(M)\propto M^{2}$ bits---an
area (holographic) law---and that this quadratic law strictly dominates any fixed
linear budget beyond an explicit crossover mass. Nevertheless a robustness theorem
holds: any storage law finite for every finite mass leaves the discoverable
fraction at zero. The governing dichotomy is finite-versus-infinite capacity, not
slow-versus-fast growth.
\end{abstract}

\maketitle

\section{Introduction}
Two intuitions about mathematics pull in opposite directions: that it is
\emph{inexhaustible} (always another theorem) and that it is \emph{enumerable}
(fix the axioms and the consequences are mechanically generable). Both are made
precise by one fact: the set of provable statements over a finite alphabet is
countably infinite. We take this seriously as a physical statement and ask what
an idealized but physically constrained agent can discover, given the finite
operation budget the universe imposes through its eventual heat death. The central
result is that, against a countably infinite target, any finite budget captures a
set of density zero (Theorem~\ref{thm:zero}), and that this verdict survives even
holographic (area-law) black-hole memory (Theorems~\ref{thm:bh}--\ref{thm:robust}).

\section{Definitions and setup}

\begin{definition}[Strings]
Fix a finite alphabet $\Sigma$ with $|\Sigma|=a\ge 2$ symbols expressive enough
for the language of first-order set theory. A \emph{statement} is a finite string
over $\Sigma$, and $\Sigma^{*}=\bigcup_{n\ge 0}\Sigma^{n}$ with
$|\Sigma^{n}|=a^{n}$.
\end{definition}

\begin{definition}[Theorems]
Fix ZFC together with a sound and complete deductive calculus. A statement
$\varphi\in\Sigma^{*}$ is a \emph{theorem} if there is a finite derivation of
$\varphi$ from ZFC; write $T=\{\varphi\in\Sigma^{*}:\mathrm{ZFC}\vdash\varphi\}$.
We assume ZFC is consistent.
\end{definition}

\begin{definition}[Budgeted enumerator]
An \emph{enumerator} is a function $E:\mathbb{N}\to\Sigma^{*}$ with range in $T$.
A \emph{budgeted enumerator} is a pair $(E,N)$ with $N\in\mathbb{N}$ a maximum
operation count; it exhibits a finite set
$D(E,N)=\{E(0),\dots,E(m-1)\}\subseteq T$ with $m\le N$.
\end{definition}

\begin{definition}[Density along an enumeration]
For a bijection $t:\mathbb{N}\to T$ and $D\subseteq T$, the \emph{density of $D$
along $t$} is
$\delta_t(D)=\lim_{n\to\infty}\frac{\#\{k<n:t_k\in D\}}{n}$ when it exists.
\end{definition}

\begin{definition}[Storage law]
A \emph{storage law} is a nondecreasing $I:[0,\infty)\to[0,\infty)$, with $I(M)$
the number of bits storable at mass $M$. It is \emph{linear} if $I(M)=\beta M$,
\emph{area/quadratic} if $I(M)=\gamma M^{2}$, and \emph{finitary} if
$I(M)<\infty$ for every finite $M$.
\end{definition}

\section{Countability of the set of theorems}

\begin{theorem}[Countability of strings]
For a finite alphabet with $a\ge 1$ symbols, $\Sigma^{*}$ is countably infinite.
\end{theorem}
\begin{proof}[Proof sketch]
Partition $\Sigma^{*}=\bigsqcup_{n\ge0}\Sigma^{n}$ with $|\Sigma^{n}|=a^{n}$
finite; a countable union of finite sets is countable. It is infinite since each
$\Sigma^{n}$ is nonempty. Shortlex order gives an explicit bijection
$\mathbb{N}\to\Sigma^{*}$.
\end{proof}

\begin{theorem}[Countable infinitude of theorems]
The set $T$ is countably infinite.
\end{theorem}
\begin{proof}[Proof sketch]
As a subset of a countable set, $T$ is countable. The distinct sentences
$\varphi_n:\equiv(\underline{0}\ne\underline{n+1})$ are theorems of ZFC, giving an
injection $\mathbb{N}\hookrightarrow T$, so $T$ is infinite.
\end{proof}

\begin{theorem}[Finite-index discoverability]
For a bijection $t:\mathbb{N}\to T$ and any $\varphi\in T$ there is a finite $k$
with $t_k=\varphi$; an unbudgeted enumerator reaches $\varphi$ in finitely many
steps.
\end{theorem}
\begin{proof}[Proof sketch]
Take $k=t^{-1}(\varphi)\in\mathbb{N}$.
\end{proof}

\section{The finite budget forces density zero}

\begin{lemma}[Budget bounds output]\label{lem:budget}
A budgeted enumerator $(E,N)$ satisfies $|D(E,N)|\le N$.
\end{lemma}
\begin{proof}[Proof sketch]
Each distinct output costs at least one operation.
\end{proof}

\begin{theorem}[Discoverable fraction is zero]\label{thm:zero}
For any bijection $t:\mathbb{N}\to T$ and any finite $D\subseteq T$,
$\delta_t(D)=0$.
\end{theorem}
\begin{proof}[Proof sketch]
Since $D$ is finite, $\#\{k<n:t_k\in D\}\le|D|$, so
$0\le \frac{\#\{k<n:t_k\in D\}}{n}\le \frac{|D|}{n}\to 0$; squeeze.
\end{proof}

\begin{corollary}[Thermodynamic horizon]
With $N\le N_{\max}\approx10^{120}$, any physically realizable discovery process
has discoverable fraction $0$: almost every theorem, in density, is physically
undiscoverable.
\end{corollary}

\section{Holographic storage and the Bekenstein bound}

\begin{theorem}[Quadratic (area) storage law]\label{thm:bh}
A Schwarzschild black hole of mass $M$ stores
\[
I(M)=\frac{4\pi G}{\hbar c\ln 2}\,M^{2}=\gamma M^{2},\qquad
\gamma=\frac{4\pi G}{\hbar c\ln 2}>0.
\]
\end{theorem}
\begin{proof}[Proof sketch]
The Schwarzschild radius $r_s=2GM/c^{2}$ gives area
$A=4\pi r_s^{2}=\frac{16\pi G^{2}}{c^{4}}M^{2}$. The Bekenstein--Hawking entropy
$S_{\mathrm{BH}}=\frac{k_Bc^{3}}{4G\hbar}A=\frac{4\pi k_BG}{\hbar c}M^{2}$;
converting to bits by $I=S/(k_B\ln 2)$ yields $\gamma M^{2}$. Radius scales as
$M$, area as $M^{2}$, and information with area.
\end{proof}

\begin{theorem}[Quadratic dominates linear beyond a crossover]\label{thm:cross}
For $I_{\mathrm{lin}}(M)=\beta M$ and $I_{\mathrm{hol}}(M)=\gamma M^{2}$, let
$M^{\star}=\beta/\gamma$. Then $I_{\mathrm{hol}}(M)>I_{\mathrm{lin}}(M)$ for all
$M>M^{\star}$, with equality at $M^{\star}$.
\end{theorem}
\begin{proof}[Proof sketch]
$\gamma M^{2}-\beta M=M(\gamma M-\beta)>0 \iff M>\beta/\gamma$ for $M>0$.
\end{proof}

\begin{theorem}[Robustness of density zero]\label{thm:robust}
For any finitary storage law $I$ and finite mass $M$, the stored set is finite, so
by Theorem~\ref{thm:zero} the discoverable fraction is $0$. A positive fraction
requires $I(M)=\infty$ at some finite $M$.
\end{theorem}
\begin{proof}[Proof sketch]
Finite bit-capacity encodes finitely many strings; apply Theorem~\ref{thm:zero}.
A positive density needs an infinite stored set, hence infinite finite-mass
capacity.
\end{proof}

\begin{corollary}[The decisive dichotomy]
Increasing the growth rate of a finitary storage law (linear $\to$ quadratic
$\to$ super-polynomial) changes the rate of approach to zero and shifts
$M^{\star}$, but never the limit, which is zero. The operative distinction is
finite versus infinite capacity, not slow versus fast growth.
\end{corollary}

\section{Discussion and future directions}
Provable mathematics is inexhaustible in the mildest way (a single countable list
with finite indices) while the universe is exhaustible in the strongest way
(finitely many operations before heat death). The zero is structural, following
from cardinality and a squeeze rather than any limit on algorithmic ingenuity;
holography helps (the area law dominates any linear budget past $M^{\star}$) but
"more" is not "enough" against an infinite target. Future work: (1) length-graded
enumerations with reciprocal-rate decay optimal across orderings; (2) area-law
optimality of Bekenstein--Hawking storage at fixed enclosed energy; (3) the
crossover mass as a genuine phase boundary between budget-limited and
enumeration-limited regimes; (4) robustness of fraction-zero under any finitary,
even super-polynomial, storage law.

\end{document}

