from __future__ import annotations
import itertools
from typing import Iterator

def shortlex_enumeration(alphabet: str) -> Iterator[str]:
    """Bijection N -> Sigma*: yield every finite string exactly once."""
    length: int = 0
    while True:
        for tup in itertools.product(alphabet, repeat=length):
            yield "".join(tup)
        length += 1

from __future__ import annotations
from fractions import Fraction

def discovered_fraction(budget: int, index: int) -> Fraction:
    """Exact discoverable fraction min(budget, index)/index."""
    if index <= 0:
        return Fraction(0)
    return Fraction(min(budget, index), index)

